{# Code body: highlighted segments, up to 13 lines at 34px leading #}
{% set seg_lines = code_segments %}
{% set lines = code_lines %}
{% set max_lines = lines | length %}

  {% set ns = namespace(y = 192) %}
  {% for i in range(13) %}
    {% if i < max_lines %}
      {% set plain_line = lines[i] %}
      {% if seg_lines is defined and seg_lines | length > i %}
        {% set seg_line = seg_lines[i] %}
        {% for seg in seg_line %}{% if seg.c %}{{ seg.t }}{% else %}{{ seg.t }}{% endif %}{% endfor %}
      {% else %}
        {{ plain_line }}
      {% endif %}
      {% set ns.y = ns.y + 33 %}
    {% endif %}
  {% endfor %}


